const alignments=new Set(['left','center','right','justify']);
function textOf(node){let text='';for(const child of node.childNodes){if(child.nodeType===3)text+=child.nodeValue;else if(child.nodeName==='BR')text+='\n';else text+=textOf(child);}return text;}
export class RichEditor {
 constructor(element,onChange,onSelection){this.element=element;this.onChange=onChange;this.onSelection=onSelection;this.savedRange=null;
  element.addEventListener('input',()=>{this.ensureParagraphs();this.remember();onChange();});
  element.addEventListener('beforeinput',e=>{if(e.inputType==='insertParagraph'){e.preventDefault();this.insertBreak();onChange();}else if(e.inputType==='insertLineBreak'){e.preventDefault();this.insertSoftBreak();onChange();}});
  element.addEventListener('paste',e=>{e.preventDefault();this.insertText(e.clipboardData?.getData('text/plain')||'');onChange();});
  element.addEventListener('drop',e=>{e.preventDefault();this.insertText(e.dataTransfer?.getData('text/plain')||'');onChange();});
  element.addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();this.insertText('    ');onChange();}});
  document.addEventListener('selectionchange',()=>{if(this.remember())onSelection?.(this.selectedAlign());});
 }
 createParagraph(text='',align='left'){const p=document.createElement('p');p.dataset.align=align;p.style.textAlign=align;const pieces=text.split('\n');pieces.forEach((part,i)=>{if(i)p.append(document.createElement('br'));if(part)p.append(document.createTextNode(part));});if(!p.childNodes.length)p.append(document.createElement('br'));return p;}
 setParagraphs(paragraphs){this.element.replaceChildren(...paragraphs.map(p=>this.createParagraph(p.text,alignments.has(p.align)?p.align:'left')));if(!this.element.children.length)this.element.append(this.createParagraph());this.savedRange=null;this.onSelection?.('left');}
 ensureParagraphs(){if([...this.element.childNodes].every(n=>n.nodeName==='P')&&this.element.children.length)return;const paragraphs=[];for(const node of this.element.childNodes){if(node.nodeName==='P')paragraphs.push(node);else if(node.nodeName==='DIV')paragraphs.push(this.createParagraph(textOf(node).replace(/\n$/,''),node.style.textAlign||'left'));else if(node.nodeName==='BR')paragraphs.push(this.createParagraph());else if(node.textContent)paragraphs.push(this.createParagraph(node.textContent));}this.element.replaceChildren(...paragraphs);if(!paragraphs.length)this.element.append(this.createParagraph());this.caretEnd(this.element.lastElementChild);}
 getParagraphs(){return [...this.element.children].map(p=>{let text=textOf(p);if(p.childNodes.length===1&&p.firstChild.nodeName==='BR')text='';return {text,align:alignments.has(p.dataset.align)?p.dataset.align:'left'};});}
 remember(){const sel=window.getSelection();if(!sel?.rangeCount)return false;const range=sel.getRangeAt(0);if(!this.element.contains(range.startContainer)||!this.element.contains(range.endContainer))return false;this.savedRange=range.cloneRange();return true;}
 normalizeRange(range){if(range.collapsed&&range.startContainer===this.element){if(range.startOffset>=this.element.children.length)this.caretEnd(this.element.lastElementChild);else this.setCaret(this.element.children[range.startOffset],0);return window.getSelection().getRangeAt(0);}return range;}
 range(){const sel=window.getSelection();if(sel?.rangeCount&&this.element.contains(sel.getRangeAt(0).commonAncestorContainer))return this.normalizeRange(sel.getRangeAt(0));if(this.savedRange&&this.element.contains(this.savedRange.startContainer)&&this.element.contains(this.savedRange.endContainer)){sel.removeAllRanges();sel.addRange(this.savedRange.cloneRange());return this.normalizeRange(sel.getRangeAt(0));}this.caretEnd(this.element.lastElementChild);return sel.getRangeAt(0);}
 paragraphFor(node){const element=node.nodeType===1?node:node.parentElement;return element?.closest('p')?.parentElement===this.element?element.closest('p'):null;}
 selectedParagraphs(){const range=this.savedRange;if(!range||!this.element.contains(range.startContainer))return [this.element.firstElementChild];if(range.collapsed)return [this.paragraphFor(range.startContainer)||this.element.children[Math.min(range.startOffset,this.element.children.length-1)]];return [...this.element.children].filter(p=>range.intersectsNode(p));}
 selectedAlign(){const values=new Set(this.selectedParagraphs().map(p=>p.dataset.align));return values.size===1?[...values][0]:null;}
 applyAlign(align){if(!alignments.has(align))return;this.remember();for(const p of this.selectedParagraphs()){p.dataset.align=align;p.style.textAlign=align;}this.onSelection?.(align);this.onChange();}
 caretEnd(p){const range=document.createRange();range.selectNodeContents(p);range.collapse(false);const sel=window.getSelection();sel.removeAllRanges();sel.addRange(range);this.remember();}
 setCaret(node,offset=0){const range=document.createRange();range.setStart(node,offset);range.collapse(true);const sel=window.getSelection();sel.removeAllRanges();sel.addRange(range);this.remember();}
 deleteSelection(){let range=this.range();if(range.collapsed)return range;const start=this.paragraphFor(range.startContainer),end=this.paragraphFor(range.endContainer);const between=start&&end&&start!==end?[...this.element.children].slice([...this.element.children].indexOf(start)+1,[...this.element.children].indexOf(end)):[];range.deleteContents();between.forEach(p=>p.remove());if(start&&end&&start!==end&&end.isConnected){const marker=document.createTextNode('');start.append(marker,...end.childNodes);end.remove();this.setCaret(marker,0);range=this.range();}this.ensureParagraphs();return this.range();}
 insertText(text){const parts=text.replace(/\r\n?/g,'\n').split('\n');this.deleteSelection();for(let i=0;i<parts.length;i++){if(i)this.insertBreak();if(parts[i]){const range=this.range(),p=this.paragraphFor(range.startContainer);if(p?.childNodes.length===1&&p.firstChild.nodeName==='BR'){p.replaceChildren();range.setStart(p,0);range.collapse(true);}const node=document.createTextNode(parts[i]);range.insertNode(node);this.setCaret(node,node.length);}}this.remember();}
 insertBreak(){const range=this.deleteSelection(),p=this.paragraphFor(range.startContainer)||this.element.firstElementChild,tail=document.createRange();tail.setStart(range.startContainer,range.startOffset);tail.setEnd(p,p.childNodes.length);const content=tail.extractContents(),next=this.createParagraph('',p.dataset.align||'left');next.replaceChildren(content);if(!next.childNodes.length)next.append(document.createElement('br'));if(!p.childNodes.length)p.append(document.createElement('br'));p.after(next);this.setCaret(next,0);this.onSelection?.(next.dataset.align);}
 insertSoftBreak(){const range=this.deleteSelection(),p=this.paragraphFor(range.startContainer);if(p?.childNodes.length===1&&p.firstChild.nodeName==='BR'){p.replaceChildren();range.setStart(p,0);range.collapse(true);}const br=document.createElement('br'),tail=document.createTextNode('');range.insertNode(br);br.after(tail);this.setCaret(tail,0);}
}
